const knownHeroNames=Object.values(storyCast).flatMap(c=>[c.ar,c.en]);
function syncHeroName(){if(!draft.name||knownHeroNames.includes(draft.name)){const c=characterById(draft.character),cast=draft.gender==='female'?'somoud':c.givenName==='mudrik'?'mudrik':'isa';draft.name=castName(cast,draft.storyLanguage)}}
const makeGenderSample=makeSample;makeSample=function(){draft.gender=heroGender(draft);draft.character=matchingCharacter(draft.character,draft.gender);const result=makeGenderSample();result.gender=draft.gender;return result};
Object.assign(characterDefaultStory,{'engineer-boy':'bridge-builders','engineer-girl':'bridge-builders','mechanic-boy':'toy-wheel','mechanic-girl':'bicycle-bell','pilot-boy':'pilot-wind','pilot-girl':'paper-flight','police-boy':'crossing-clue','police-girl':'help-desk','medic-boy':'teddy-ambulance','medic-girl':'clear-route','firefighter-boy':'fire-engine','firefighter-girl':'exit-map'});
const startGenderStory=launchStory;launchStory=function(options={}){startGenderStory(options);if(options.character){draft.gender=characterById(options.character).gender;draft.character=options.character;syncHeroName();renderStudio()}};
const renderPersonalStudio=renderStudio;renderStudio=function(){
 draft.gender=heroGender(draft);renderPersonalStudio();
 if(step===0){
  const form=$('#heroForm'),name=form.elements.name;
  const field=document.createElement('label');field.className='field';field.innerHTML=`${t('بطل الحكاية','Story hero')}<select id="heroGender" name="gender"><option value="male" ${draft.gender==='male'?'selected':''}>${t('ولد — بطل','Boy — hero')}</option><option value="female" ${draft.gender==='female'?'selected':''}>${t('بنت — بطلة','Girl — heroine')}</option></select>`;form.querySelector('.form-grid').insertBefore(field,form.querySelector('.field:nth-child(2)'));
  const note=document.createElement('p');note.className='gender-note';note.textContent=t('يتكيّف السرد والضمائر والأفعال مع اختيارك، مع الاحتفاظ باسم الطفل.','Story wording, verbs and pronouns follow your selection while keeping the child’s name.');field.append(note);
  const update=()=>{$('#modalTitle').textContent=draft.gender==='female'?t('لنتعرّف على بطلة الحكاية','Meet the story’s heroine'):t('لنتعرّف على بطل الحكاية','Meet the story’s hero');name.placeholder=draft.gender==='female'?t('مثلًا: صمود','e.g. Somoud'):t('مثلًا: عيسى أو مدرك','e.g. Isa or Mudrik')};update();
  $('#heroGender').onchange=e=>{draft.name=name.value.trim();draft.storyLanguage=form.elements.storyLanguage.value;draft.gender=e.target.value;draft.character=matchingCharacter(draft.character,draft.gender);syncHeroName();name.value=draft.name;update()};
  name.addEventListener('change',()=>{const cast=Object.entries(storyCast).find(([,c])=>[c.ar,c.en].includes(name.value.trim()));if(cast){draft.name=name.value.trim();draft.gender=cast[0]==='somoud'?'female':'male';$('#heroGender').value=draft.gender;draft.character=matchingCharacter(draft.character,draft.gender);update()}});
  const submit=form.onsubmit;form.onsubmit=e=>{draft.gender=$('#heroGender').value;draft.character=matchingCharacter(draft.character,draft.gender);submit(e)};
 }
 if(step===1){
  $('#modalTitle').textContent=draft.gender==='female'?t('بطلتك… وألف احتمال','Her story. A world of possibilities.'):t('بطلك… وألف احتمال','His story. A world of possibilities.');
  const badge=document.createElement('div');badge.className='hero-identity-pill';badge.textContent=(draft.gender==='female'?t('✦ بطولة ','✦ Her story: '):t('✦ بطولة ','✦ His story: '))+draft.name;$('#studioContent .studio-progress').after(badge);
  document.querySelectorAll('[data-pick-character]').forEach(b=>b.onclick=()=>{draft.narrative=$('#narrative').value;draft.landmark=$('#landmark').value;draft.tone=$('#tone').value;draft.plan=$('#plan').value;draft.character=b.dataset.pickCharacter;draft.gender=characterById(draft.character).gender;syncHeroName();renderStudio()});
 }
 if(step===2&&story){const badge=$('#studioContent .preview-text .badge');if(badge&&!story.historical)badge.textContent=(story.gender==='female'?t('بطلتك ','Your heroine, '):t('بطلك ','Your hero, '))+story.name+t(story.gender==='female'?' · حكاية تتكيّف معها':' · حكاية تتكيّف معه',' · A story of their own');}
};

function refreshHikayaDesign(){
 document.querySelectorAll('.brand').forEach(a=>{a.setAttribute('aria-label','حكاية · HIKAYA');const title=a.querySelector('[data-t="brand"]')||a.querySelector('span:not(.brand-icon)');if(title)title.textContent='حكاية'});
 let stats=$('.hero-stats');if(!stats){stats=document.createElement('div');stats.className='hero-stats';$('.hero-notes').after(stats)}stats.innerHTML=`<div><strong>${storyCatalog.length}</strong><span>${t('حكاية تنتظره','stories to explore')}</span></div><div><strong>${characters.length}</strong><span>${t('شخصية وحلم','characters & dreams')}</span></div><div><strong>ع / EN</strong><span>${t('حكايته بلغتين','two story languages')}</span></div>`;
 let dream=$('#dreamShelf');if(!dream){dream=document.createElement('section');dream.id='dreamShelf';dream.className='dream-shelf wrap';$('.formats').before(dream)}
 const dreams=[['bridge-builders','engineer-girl','مهندسة الغد','Future engineer'],['pilot-wind','pilot-boy','رحلة فوق الغيم','Above the clouds'],['fire-engine','firefighter-boy','شجاعة تهتمّ','Courage that cares'],['dad-kite','omani-boy','أنا وأبي','Dad & me',0],['mum-recipe','omani-girl','أنا وأمي','Mum & me',1],['lamb-bell','omani-girl','أصدقاء المزرعة','Farm friends',3]];
 dream.innerHTML=`<div class="dream-intro"><span class="overline">${t('حلم صغير… وحكاية كبيرة','LITTLE DREAMS. BIG STORIES.')}</span><h2>${t('أيّ حلم نختار اليوم؟','Who would they love to be today?')}</h2><p>${t('من ورشة الأفكار إلى حضن العائلة، كل شغف له حكاية.','From a workshop of ideas to the warmth of family. Every passion has a story.')}</p></div><div class="dream-tiles">${dreams.map(([id,c,ar,en,scene])=>`<button class="dream-tile" data-dream="${id}">${scene===undefined?charArt(characterById(c)):`<div class="character-art" role="img" aria-label="${esc(t(ar,en))}" style="background-image:url('assets/book/family-adventures.webp');background-size:400% 200%;background-position:${scene%4*100/3}% ${Math.floor(scene/4)*100}%"></div>`}<span>${t(ar,en)} <b>↗</b></span></button>`).join('')}</div>`;dream.querySelectorAll('[data-dream]').forEach(b=>b.onclick=()=>launchTale(b.dataset.dream));
}
