// Rasterize the new bilingual wordmark with the local Arabic font for portable PNG use.
$('#downloadBrandLogo').onclick=async()=>{await document.fonts.load('800 300px "Hikaya Arabic"');const canvas=document.createElement('canvas');canvas.width=1560;canvas.height=510;const ctx=canvas.getContext('2d');ctx.scale(3,3);const mark=await bookImage('assets/hikaya-symbol.svg');ctx.drawImage(mark,366,11,148.8,148.8);ctx.direction='rtl';ctx.textAlign='right';ctx.fillStyle='#164D42';ctx.font='800 100px "Hikaya Arabic",sans-serif';ctx.fillText('حكاية',340,106);ctx.direction='ltr';ctx.font='700 23px Arial,sans-serif';ctx.fillStyle='#796746';const letters=[...'HIKAYA'],gap=7,total=letters.reduce((v,c)=>v+ctx.measureText(c).width,0)+gap*5;let x=337-total;ctx.textAlign='left';for(const c of letters){ctx.fillText(c,x,147);x+=ctx.measureText(c).width+gap}ctx.beginPath();ctx.moveTo(88,122);ctx.bezierCurveTo(130,136,174,136,213,125);ctx.strokeStyle='#E68068';ctx.lineWidth=3;ctx.lineCap='round';ctx.stroke();download(await canvasBlob(canvas),'hikaya-logo.png')};

